inner="\nfrom pathlib import Path\nimport json,sys,numpy as np,torch\nfrom torch import nn\nfrom torch.nn import functional as F\nfrom experiments.pamf_phase1_flow import experiment as core,physical_rich_router_experiment as g,feature_conditioned_experiment as fs\nroot=Path('/home/szu2070436088/2510044040/CV-SincNet');torch.set_num_threads(2)\nmodels=g.load_models(root,'cpu');teacher,contract,dura,*_=models;cache,clean,roles=core.data(root,contract)\nfrom leo_practical.channel import Config,receiver_for_session,stable_seed,normalize_input\nfrom leo_practical.residual import ResidualChannel\nids=np.load(cache/'train/physical_ids.npy',allow_pickle=False);rx=np.load(cache/'train/rx.npy',allow_pickle=False);day=np.load(cache/'train/day.npy',allow_pickle=False)\n# Exclude IDs used by the earlier 8,192-ID consensus probe and 4,096-ID\n# diffusion pilots. Other historical source diagnostics may still overlap.\nspecs=(('L_s',2048,1024,2048),('U_s',6144,3072,6144));previous={}\nfor seed,column in ((2026110251,1),(2026110301,2)):\n gen=np.random.default_rng(seed)\n for spec in specs:\n  role=spec[0];available=np.flatnonzero(roles==role);previous.setdefault(role,[]).append(gen.choice(available,size=spec[column],replace=False))\nrng=np.random.default_rng(2026110321);groups=[]\nfor role,_,__,take in specs:\n available=np.flatnonzero(roles==role);available=np.setdiff1d(available,np.unique(np.concatenate(previous[role])),assume_unique=True)\n assert len(available)>=take;groups.append(np.sort(rng.choice(available,size=take,replace=False)))\nfixed=np.concatenate(groups);assert len(fixed)==len(np.unique(fixed))==8192\nsource_rx=rx[fixed];source_day=day[fixed];split=np.full(len(fixed),-1,dtype=np.int64)\nsplit[np.isin(source_rx,[1,3,4])&np.isin(source_day,[1,2])]=0\nsplit[np.isin(source_rx,[4,6])&(source_day==3)]=1\nsplit[(source_rx==8)&(source_day==3)]=2\nassert all(int((split==i).sum())>200 for i in range(3))\nkeep=split>0;fixed=fixed[keep];source_rx=source_rx[keep];source_day=source_day[keep];split=split[keep];assert len(fixed)>1000\nviews=('clean','practical_low_suburban','practical_mid_urban','practical_low_urban');namespace='phase1-source-conditional-diffusion-2026110302';data={}\nwith torch.no_grad():\n for view in views:\n  if view=='clean':received=np.asarray(clean[fixed],dtype=np.float32)\n  else:\n   cfgs={snr:Config(fs_hz=25e6,fc_hz=2462e6,scenario=view,processing_route='residual',mode='post_sync',equalization_enabled=False,reference_snr_db=snr,boundary='reflect') for snr in (10.,20.,30.)}\n   received=[]\n   for position,j in enumerate(fixed):\n    pid=str(ids[j]);snr=(10.,20.,30.)[stable_seed(2026110312,'diffusion-source-hard-snr',view,pid)%3] if split[position]==0 else 30.;cfg=cfgs[snr]\n    session='rx%d:day%d:eq1'%(int(rx[j]),int(day[j]));hw=receiver_for_session(cfg,2026110303,session)\n    v=np.asarray(clean[j],dtype=np.float64);signal,_=normalize_input(v[0]+1j*v[1]);result,meta=ResidualChannel(cfg,stable_seed(2026110302,namespace,view,pid),hw).process(signal)\n    assert np.isfinite(result).all() and not meta['channel_equalization_applied'];received.append(np.stack((result.real,result.imag)).astype(np.float32))\n   received=np.stack(received)\n  anchors=[];rawp=[];basep=[]\n  for start in range(0,len(fixed),32):\n   x=core.tensor(received[start:start+32],'cpu');a=dura(x);anchors.append(a.cpu())\n   rawp.append(F.softmax(teacher.classify_features(teacher.features(x)),1).cpu())\n   basep.append(F.softmax(teacher.classify_features(teacher.features(a)),1).cpu())\n  data[view]=dict(received=core.tensor(received,'cpu'),anchor=torch.cat(anchors),rawp=np.from_dlpack(torch.cat(rawp).contiguous()),basep=np.from_dlpack(torch.cat(basep).contiguous()))\n  print('SCALED_DIFFUSION_SOURCE_BASELINES_FIXED',view,flush=True)\nprint('ALL_SOURCE_BASELINES_FIXED_BEFORE_SOURCE_LABELS',flush=True)\nclass Block(nn.Module):\n def __init__(self,dilation):\n  super().__init__();self.a=nn.Conv1d(32,32,3,padding=dilation,dilation=dilation);self.b=nn.Conv1d(32,32,3,padding=1)\n def forward(self,x):return x+.2*self.b(F.gelu(self.a(F.gelu(x))))\n\nclass NoiseNet(nn.Module):\n def __init__(self):\n  super().__init__();self.enter=nn.Conv1d(7,32,5,padding=2);self.blocks=nn.Sequential(Block(1),Block(2),Block(4));self.exit=nn.Conv1d(32,2,3,padding=1)\n def forward(self,z,a,x,sigma):\n  t=sigma[:,None,None].expand(-1,1,z.shape[-1]);return self.exit(self.blocks(self.enter(torch.cat((z,a,x,t),1))))\nexpected=json.load(sys.stdin);net=NoiseNet();net.load_state_dict({k:torch.tensor(v,dtype=torch.float32) for k,v in expected['model_state'].items()},strict=True);net.eval()\nstarts=(.1,.2,.3);alphas=(.25,.5,1.);rules=('fixed_01','fixed_02','fixed_03','ratio_01_03','ratio_03_06','ratio_06_10');predictions={};ratios={}\ndef generate_from(a,x,start):\n z=(1-start*start)**.5*a;schedule=[v for v in (.3,.2,.1,.05) if v<=start+1e-8]\n for i,s in enumerate(schedule):\n  next_s=schedule[i+1] if i+1<len(schedule) else 0.;st=torch.full((len(z),),s);noise=net(z,a,x,st);clean_hat=(z-s*noise)/(1-s*s)**.5\n  z=(1-next_s*next_s)**.5*clean_hat+next_s*noise\n return z\nwith torch.no_grad():\n for view in views:\n  buckets=[[[] for _ in alphas] for _ in starts];rs=[]\n  for start in range(0,len(fixed),64):\n   a=data[view]['anchor'][start:start+64];x=data[view]['received'][start:start+64]\n   ratio=((x-a).square().mean((1,2))/(x.square().mean((1,2)).clamp_min(1e-8))).sqrt();gate=(ratio/.1).clamp(0,1);rs.append(ratio.cpu())\n   for j,sigma in enumerate(starts):\n    generated=generate_from(a,x,sigma)\n    for k,alpha in enumerate(alphas):\n     wave=a+alpha*gate[:,None,None]*(generated-a);assert torch.isfinite(wave).all()\n     buckets[j][k].append(teacher.classify_features(teacher.features(wave)).argmax(1).cpu())\n  ratios[view]=np.from_dlpack(torch.cat(rs).contiguous())\n  predictions[view]=np.stack([np.stack([np.from_dlpack(torch.cat(v).contiguous()) for v in row],axis=1) for row in buckets],axis=1)\n  assert predictions[view].shape==(len(fixed),len(starts),len(alphas));print('ADAPTIVE_DIFFUSION_SOURCE_PREDICTIONS_FIXED',view,flush=True)\nprint('ALL_ADAPTIVE_SOURCE_PREDICTIONS_FIXED_BEFORE_SOURCE_LABELS',flush=True)\nlabels=fs.source_labels(root,cache,clean,roles,contract);labeled=roles[fixed]=='L_s';assert np.all(labels[fixed[~labeled]]==-1)\nref=data['clean']['rawp'];teacher_target=ref.argmax(1);valid=labeled|(ref.max(1)>=.95);target=np.where(labeled,labels[fixed],teacher_target)\ndef choose(view,rule,alpha_index):\n r=ratios[view]\n if rule.startswith('fixed_'):t=np.full(len(r),{'fixed_01':0,'fixed_02':1,'fixed_03':2}[rule],dtype=np.int64)\n else:\n  lo,hi={'ratio_01_03':(.1,.3),'ratio_03_06':(.3,.6),'ratio_06_10':(.6,1.)}[rule];t=np.where(r<lo,0,np.where(r<hi,1,2))\n return predictions[view][np.arange(len(r)),t,alpha_index]\ndef evaluate(rule,alpha_index,part,group=None):\n mask=(split==part)&valid;clean_mask=(split==part)\n if group is not None:mask &= source_rx==group;clean_mask &= source_rx==group\n per={};clean_net=0\n for view in views:\n  out=choose(view,rule,alpha_index);base=data[view]['basep'].argmax(1);old=base==target;new=out==target;lm=mask&labeled\n  per[view]=dict(valid_count=int(mask.sum()),L_s_count=int(lm.sum()),U_confident_count=int((mask&~labeled).sum()),baseline=int((mask&old).sum()),student=int((mask&new).sum()),repairs=int((mask&~old&new).sum()),damages=int((mask&old&~new).sum()),L_s_baseline=int((lm&old).sum()),L_s_student=int((lm&new).sum()))\n  if view=='clean':clean_net=int((clean_mask&(out==teacher_target)).sum()-(clean_mask&(base==teacher_target)).sum())\n return per,clean_net\nvalidation=[];best={'kind':'dura','validation_net':0}\nfor rule in rules:\n for ai,alpha in enumerate(alphas):\n  per,clean=evaluate(rule,ai,1);changes={v:per[v]['student']-per[v]['baseline'] for v in views[1:]};net_gain=sum(changes.values());groups_v={}\n  for group in (4,6):\n   gp,gclean=evaluate(rule,ai,1,group);count=int(((split==1)&(source_rx==group)).sum());gc={v:gp[v]['student']-gp[v]['baseline'] for v in views[1:]}\n   groups_v[str(group)]=dict(n=count,net=sum(gc.values()),per_view=gc,clean_teacher_net=gclean)\n  validation.append(dict(rule=rule,alpha=alpha,net=net_gain,per_view=changes,clean_teacher_net=clean,groups=groups_v))\n  guards=all(z['net']>=0 and z['clean_teacher_net']>=-.01*z['n'] and min(z['per_view'].values())>=-.005*z['n'] for z in groups_v.values())\n  if net_gain>best['validation_net'] and guards:best=dict(kind='adaptive_diffusion',rule=rule,alpha=alpha,validation_net=net_gain)\nif best['kind']=='dura':heldout=None;clean_net=None\nelse:heldout,clean_net=evaluate(best['rule'],alphas.index(best['alpha']),2)\ncontrol,control_clean=evaluate('fixed_03',1,2)\nprint('SOURCE_ADAPTIVE_DIFFUSION_PROBE '+json.dumps(dict(status='SOURCE_ONLY_ADAPTIVE_DIFFUSION_PROBE',source_ids=len(fixed),validation_ids=int((split==1).sum()),heldout_ids=int((split==2).sum()),starts=list(starts),alphas=list(alphas),rules=list(rules),validation=validation,selected=best,heldout=heldout,heldout_clean_teacher_net=clean_net,fixed_03_alpha_05_control=control,control_clean_teacher_net=control_clean,\n U_s_labels_read=0,V_reads=0,test_IQ_reads=0,predictions_before_source_labels=True,\n caveat='All options use the same frozen guided diffusion weights and frozen Tri-SIG-TIME SSL. Source IDs exclude earlier consensus and diffusion pilot samples but can overlap other source probes; fixed experts saw source records. Residual is a proxy, not calibrated SNR. Source simulator is not validated satellite data; prior observed Phase1 test findings informed exploration.'),ensure_ascii=False),flush=True)\n"
